import numpy as np

# MECHANISM: Use a combination of remaining capacity and a penalty for choosing bins with lower capacity.

def priority(item, bins):
    def s(b, item):
        g = b - item
        penalty = max(0, b - 100)  # Penalty for bins with capacity less than 100
        return (4 - g / 2) / (1 + penalty)
    return np.array([s(b, item) for b in bins])

